import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const d=JSON.parse(`{"title":"Page 3 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"3","title":"Page 3 | Home","prev":"/page/2/","next":"/page/4/","posts":[{"title":"macOS下编译C++文件","url":"/posts/2023-10-09-macos-build-cpp/","date":"2023-10-09 12:10","tags":["C++"],"html":"<p>WebAssembly 是一种新的编译目标，可以将 C/C++ 等语言编译成 WebAssembly，然后在浏览器中运行。我最近在研究如何把<a href=\\"https://github.com/mchehab/zbar\\" target=\\"_blank\\" rel=\\"noreferrer\\">zbar</a>编译成 WebAssembly，然后在浏览器中使用。第一步就是想把官方的例子编译成二进制测试下代码，但是在 MacOS 下编译的时候遇到了一些问题，这里记录下。</p>\\n<h2 id=\\"官方例子\\" tabindex=\\"-1\\">官方例子 <a class=\\"header-anchor\\" href=\\"#官方例子\\" aria-label=\\"Permalink to &quot;官方例子&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://github.com/mchehab/zbar/blob/master/examples/scan_image.cpp\\" target=\\"_blank\\" rel=\\"noreferrer\\">scan_image.cpp</a></p>\\n<p>官方提供了一个例子，可以用来测试二维码识别功能，这个例子有两个依赖 Magick++.h 和 zbar.h，这两个库都可以通过 brew 安装。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">brew</span><span style=\\"color:#032F62\\"> install</span><span style=\\"color:#032F62\\"> imagemagick</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">brew</span><span style=\\"color:#032F62\\"> install</span><span style=\\"color:#032F62\\"> zbar</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>因为从源码编译对我来说实在是太复杂了，所以我就选择了直接安装相关依赖。</p>\\n<h2 id=\\"编译\\" tabindex=\\"-1\\">编译 <a class=\\"header-anchor\\" href=\\"#编译\\" aria-label=\\"Permalink to &quot;编译&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">g++</span><span style=\\"color:#005CC5\\"> -o</span><span style=\\"color:#032F62\\"> scan_image</span><span style=\\"color:#032F62\\"> scan_image.cpp</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>执行上面的命令，会报错：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>scan_image.cpp:1:10: fatal error: 'Magick++.h' file not found</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这是因为 Magick++.h 的头文件在 <code>/opt/homebrew/include/ImageMagick-7/Magick++.h</code>，但是 g++ 默认只会在 <code>/opt/homebrew/include</code> 目录下查找头文件，所以我们需要指定头文件的路径。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">g++</span><span style=\\"color:#005CC5\\"> -o</span><span style=\\"color:#032F62\\"> scan_image</span><span style=\\"color:#032F62\\"> scan_image.cpp</span><span style=\\"color:#005CC5\\"> -I/opt/homebrew/include/ImageMagick-7</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>执行上面的命令还是会有报错：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>/opt/homebrew/include/ImageMagick-7/MagickCore/magick-config.h:63:3: warning: \\"you should set MAGICKCORE_QUANTUM_DEPTH to sensible default set it to configure time default\\" [-W#warnings]</span></span>\\n<span class=\\"line\\"><span># warning \\"you should set MAGICKCORE_QUANTUM_DEPTH to sensible default set it to configure time default\\"</span></span>\\n<span class=\\"line\\"><span>  ^</span></span>\\n<span class=\\"line\\"><span>/opt/homebrew/include/ImageMagick-7/MagickCore/magick-config.h:64:3: warning: \\"this is an obsolete behavior please fix your makefile\\" [-W#warnings]</span></span>\\n<span class=\\"line\\"><span># warning \\"this is an obsolete behavior please fix your makefile\\"</span></span>\\n<span class=\\"line\\"><span>  ^</span></span>\\n<span class=\\"line\\"><span>/opt/homebrew/include/ImageMagick-7/MagickCore/magick-config.h:86:3: error: \\"you should set MAGICKCORE_HDRI_ENABLE\\"</span></span>\\n<span class=\\"line\\"><span># error \\"you should set MAGICKCORE_HDRI_ENABLE\\"</span></span>\\n<span class=\\"line\\"><span>  ^</span></span>\\n<span class=\\"line\\"><span>/opt/homebrew/include/ImageMagick-7/MagickCore/magick-config.h:121:3: error: \\"you should set MAGICKCORE_HDRI_ENABLE\\"</span></span>\\n<span class=\\"line\\"><span># error \\"you should set MAGICKCORE_HDRI_ENABLE\\"</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br></div></div><p>我们需要设置两个 ImageMagick 需要的编译变量：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">g++</span><span style=\\"color:#005CC5\\"> -o</span><span style=\\"color:#032F62\\"> scan_image</span><span style=\\"color:#032F62\\"> scan_image.cpp</span><span style=\\"color:#005CC5\\"> -I/opt/homebrew/include/ImageMagick-7</span><span style=\\"color:#005CC5\\"> -DMAGICKCORE_QUANTUM_DEPTH=16</span><span style=\\"color:#005CC5\\"> -DMAGICKCORE_HDRI_ENABLE=0</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>设置了这两个变量之后，还是会报错：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>Undefined symbols for architecture arm64:</span></span>\\n<span class=\\"line\\"><span>  \\"Magick::Blob::Blob()\\", referenced from:</span></span>\\n<span class=\\"line\\"><span>      _main in scan_image-727bdc.o</span></span>\\n<span class=\\"line\\"><span>  \\"_zbar_get_symbol_name\\", referenced from:</span></span>\\n<span class=\\"line\\"><span>      zbar::Symbol::get_type_name() const in scan_image-727bdc.o</span></span>\\n<span class=\\"line\\"><span>ld: symbol(s) not found for architecture arm64</span></span>\\n<span class=\\"line\\"><span>clang: error: linker command failed with exit code 1 (use -v to see invocation)</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br></div></div><p>这是因为我们只引用了头文件，却没有引用相关库的实现。我们需要指定 ImageMagick 的库文件路径，这里我使用的是 brew 安装的 ImageMagick，所以库文件在 <code>/opt/homebrew/lib/ImageMagick</code> 目录下。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">g++</span><span style=\\"color:#005CC5\\"> -o</span><span style=\\"color:#032F62\\"> scan_image</span><span style=\\"color:#032F62\\"> scan_image.cpp</span><span style=\\"color:#005CC5\\"> -I/opt/homebrew/include/ImageMagick-7</span><span style=\\"color:#005CC5\\"> -L/opt/homebrew/lib/ImageMagick</span><span style=\\"color:#005CC5\\"> -DMAGICKCORE_QUANTUM_DEPTH=16</span><span style=\\"color:#005CC5\\"> -DMAGICKCORE_HDRI_ENABLE=0</span><span style=\\"color:#005CC5\\"> -lMagick++-7.Q16HDRI</span><span style=\\"color:#005CC5\\"> -lzbar</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>同时我们需要使用 -l 参数来指定需要链接的库，这里需要链接 Magick++-7.Q16HDRI 和 zbar。</p>\\n<h2 id=\\"cmake\\" tabindex=\\"-1\\">CMake <a class=\\"header-anchor\\" href=\\"#cmake\\" aria-label=\\"Permalink to &quot;CMake&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>上面的编译命令比较长，而且如果我们需要编译多个文件的时候，就需要写很多次，所以我们可以使用 CMake 来简化编译过程。</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>cmake_minimum_required(VERSION 3.10)</span></span>\\n<span class=\\"line\\"><span>project(ScanImage)</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>set(CMAKE_CXX_STANDARD 11)</span></span>\\n<span class=\\"line\\"><span>set(CMAKE_CXX_FLAGS \\"-DMAGICKCORE_HDRI_ENABLE=1 -DMAGICKCORE_QUANTUM_DEPTH=16\\")</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>include_directories(/opt/homebrew/include/ImageMagick-7)</span></span>\\n<span class=\\"line\\"><span>link_directories(/opt/homebrew/lib/ImageMagick)</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>add_executable(ScanImage scan_image.cpp)</span></span>\\n<span class=\\"line\\"><span>target_link_libraries(ScanImage zbar Magick++-7.Q16HDRI)</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br></div></div><h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>C++ 的编译报错总是让人摸不着头脑，这里我只是简单的记录了下我遇到的问题和解决方案，希望能帮助到大家。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://stackoverflow.com/questions/17887265/how-to-include-third-party-libraries\\" target=\\"_blank\\" rel=\\"noreferrer\\">how to #include third party libraries</a></p>\\n<p><a href=\\"https://github.com/undecaf/zbar-wasm\\" target=\\"_blank\\" rel=\\"noreferrer\\">zbar-wasm</a></p>\\n"},{"title":"正则表达式匹配信用卡","url":"/posts/2023-07-09-credit-regex/","date":"2023-07-09 13:41","tags":["regex"],"html":"<p>最近在做支付相关的服务，需要检测用户输入的信用卡号是否合法，并且根据信用卡号规则显示对应的信用卡类型。这里记录一下如何使用正则表达式来匹配信用卡号。顺便说一下只有 AE 卡号的 CVV 是 4 位的，其他的都是 3 位。</p>\\n<h2 id=\\"银联卡\\" tabindex=\\"-1\\">银联卡 <a class=\\"header-anchor\\" href=\\"#银联卡\\" aria-label=\\"Permalink to &quot;银联卡&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>银联卡以 62 开头，借记卡是 19 位，信用卡是 14 位。一般支付的时候都是使用信用卡，所以我们只需要匹配 14 位的卡号。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> regex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'^62</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{14}'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"visa\\" tabindex=\\"-1\\">Visa <a class=\\"header-anchor\\" href=\\"#visa\\" aria-label=\\"Permalink to &quot;Visa&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Visa 信用卡以 4 开头，新卡长度为 16 位，旧卡长度为 13 位。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> regex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'^4[0-9]{12}(?:[0-9]{3})?'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"mastercard\\" tabindex=\\"-1\\">MasterCard <a class=\\"header-anchor\\" href=\\"#mastercard\\" aria-label=\\"Permalink to &quot;MasterCard&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>MasterCard 信用卡以 51 到 55 开头或者是以 2221–2720 开头，长度为 16 位。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> regex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'^(5[1-5]</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{0,2}|22[2-9]</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{1}|2[3-7]</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{2})</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{12}'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"amex\\" tabindex=\\"-1\\">Amex <a class=\\"header-anchor\\" href=\\"#amex\\" aria-label=\\"Permalink to &quot;Amex&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Amex 信用卡以 34 或者 37 开头，长度为 15 位。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> regex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'^3[47]</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{13}'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"jcb\\" tabindex=\\"-1\\">Jcb <a class=\\"header-anchor\\" href=\\"#jcb\\" aria-label=\\"Permalink to &quot;Jcb&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Jcb 信用卡以 35 开头，长度为 16 位。以 2131 或者 1800 开头，长度为 15 位。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> regex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'^(?:2131|1800|35</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{3})</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{11}'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"diners\\" tabindex=\\"-1\\">Diners <a class=\\"header-anchor\\" href=\\"#diners\\" aria-label=\\"Permalink to &quot;Diners&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Diners 信用卡以 36、38 或者 30[0-5] 开头，长度为 14 位。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> regex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'^3(?:0([0-5]|9)|[68]</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d)</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{11}'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>信用卡号的判断并不复杂，但是很多卡号有些特殊情况，需要注意。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://en.wikipedia.org/wiki/Payment_card_number\\" target=\\"_blank\\" rel=\\"noreferrer\\">Payment card number</a></p>\\n<p><a href=\\"https://www.regular-expressions.info/creditcard.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">Finding or Verifying Credit Card Numbers</a></p>\\n"},{"title":"无限滚动加载列表","url":"/posts/2023-06-03-scroll-loader/","date":"2023-06-03 12:55","tags":["web"],"html":"<p>滚动加载是分页显示列表常用的一个技术，具体的实现方式基本上后端都会在返回数据上给一个 <code>cursor</code> 字段，前端在请求下一页的时候会把这个字段带上，后端根据这个字段来返回下一页的数据。这种方式的好处是可以在前端缓存数据，减少请求次数，但是缺点也很明显，就是无法跳页，只能一页一页的往下翻。为此，我们要实现一个滚动加载组件，当这个组件在可视范围内的时候，会去加载下一页的数据。</p>\\n<h2 id=\\"核心技术点\\" tabindex=\\"-1\\">核心技术点 <a class=\\"header-anchor\\" href=\\"#核心技术点\\" aria-label=\\"Permalink to &quot;核心技术点&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>如果检测组件进入可视范围，我们可以使用 IntersectionObserver API，来监听元素进入可视范围。我们使用 React 实现一个组件，当这个组件进入可视范围的时候，会触发一个回调函数，这个回调函数会去加载下一页的数据。</p>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#6F42C1\\"> ScrollLoader</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">FC</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">IScrollLoaderProps</span><span style=\\"color:#24292E\\">> </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> ({</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  inView,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  updateCompleted</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> loaderRef</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useRef</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">null</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> observerRef</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useRef</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">IntersectionObserver</span><span style=\\"color:#D73A49\\"> |</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#24292E\\">>(</span><span style=\\"color:#005CC5\\">null</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> cursorRef</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useRef</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">''</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#24292E\\"> [</span><span style=\\"color:#005CC5\\">completed</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">setCompleted</span><span style=\\"color:#24292E\\">] </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> useState</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">false</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> fetchMore</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useCallback</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    inView</span><span style=\\"color:#24292E\\">?.(cursorRef.current).</span><span style=\\"color:#6F42C1\\">then</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">res</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      if</span><span style=\\"color:#24292E\\"> (res.nextCursor) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        cursorRef.current </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> res.nextCursor;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        if</span><span style=\\"color:#24292E\\"> (observerRef.current </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#24292E\\"> loaderRef.current) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">          // trigger the observer again</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          observerRef.current.</span><span style=\\"color:#6F42C1\\">unobserve</span><span style=\\"color:#24292E\\">(loaderRef.current);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          observerRef.current.</span><span style=\\"color:#6F42C1\\">observe</span><span style=\\"color:#24292E\\">(loaderRef.current);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      } </span><span style=\\"color:#D73A49\\">else</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">        setCompleted</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">        updateCompleted</span><span style=\\"color:#24292E\\">?.(</span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }, [inView, updateCompleted]);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> callbackFunction</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> IntersectionObserverCallback</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useCallback</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">    entries</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      entries.</span><span style=\\"color:#6F42C1\\">forEach</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">entry</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        if</span><span style=\\"color:#24292E\\"> (entry.isIntersecting </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#D73A49\\"> !</span><span style=\\"color:#24292E\\">completed) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">          fetchMore</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    [completed, fetchMore]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  useEffect</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    const</span><span style=\\"color:#005CC5\\"> observerOptions</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      root: </span><span style=\\"color:#005CC5\\">null</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      rootMargin: </span><span style=\\"color:#032F62\\">'0px'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      threshold: </span><span style=\\"color:#005CC5\\">0.5</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    observerRef.current </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> IntersectionObserver</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      callbackFunction,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      observerOptions</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    if</span><span style=\\"color:#24292E\\"> (loaderRef.current) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      observerRef.current.</span><span style=\\"color:#6F42C1\\">observe</span><span style=\\"color:#24292E\\">(loaderRef.current);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      if</span><span style=\\"color:#24292E\\"> (observerRef.current) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        observerRef.current.</span><span style=\\"color:#6F42C1\\">disconnect</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        observerRef.current </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }, [callbackFunction]);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (completed) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  } </span><span style=\\"color:#D73A49\\">else</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> (</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#6F42C1\\"> className</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{styles.loader} </span><span style=\\"color:#6F42C1\\">ref</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{loaderRef}></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        &#x3C;</span><span style=\\"color:#005CC5\\">Loading</span><span style=\\"color:#24292E\\"> /></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;/</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br><span class=\\"line-number\\">42</span><br><span class=\\"line-number\\">43</span><br><span class=\\"line-number\\">44</span><br><span class=\\"line-number\\">45</span><br><span class=\\"line-number\\">46</span><br><span class=\\"line-number\\">47</span><br><span class=\\"line-number\\">48</span><br><span class=\\"line-number\\">49</span><br><span class=\\"line-number\\">50</span><br><span class=\\"line-number\\">51</span><br><span class=\\"line-number\\">52</span><br><span class=\\"line-number\\">53</span><br><span class=\\"line-number\\">54</span><br><span class=\\"line-number\\">55</span><br><span class=\\"line-number\\">56</span><br><span class=\\"line-number\\">57</span><br><span class=\\"line-number\\">58</span><br><span class=\\"line-number\\">59</span><br><span class=\\"line-number\\">60</span><br><span class=\\"line-number\\">61</span><br><span class=\\"line-number\\">62</span><br><span class=\\"line-number\\">63</span><br><span class=\\"line-number\\">64</span><br><span class=\\"line-number\\">65</span><br><span class=\\"line-number\\">66</span><br><span class=\\"line-number\\">67</span><br><span class=\\"line-number\\">68</span><br></div></div><p>通过 inView 属性来传入回调函数，当组件进入可视范围的时候，会调用这个函数，然后去加载下一页的数据。这里我们使用了一个 cursor 来标记当前的页码，当请求下一页的时候，会把这个 cursor 传给后端，后端会根据这个 cursor 来返回下一页的数据。当后端返回的数据中没有 cursor 的时候，说明已经到了最后一页，这时候我们不再渲染这个组件。</p>\\n<h2 id=\\"边界情况处理\\" tabindex=\\"-1\\">边界情况处理 <a class=\\"header-anchor\\" href=\\"#边界情况处理\\" aria-label=\\"Permalink to &quot;边界情况处理&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>当用户的屏幕非常长的时候，我们需要加载很多页的数据才能填满屏幕。但是 IntersectionObserver 在组件进入可视范围的时候只会触发一次回调，所以我们需要手动去重新触发。当组件加载完数据的时候，我们会先 unobserve，然后再重新 observe 这个组件，这样就可以触发回调函数了。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>滚动加载是一个很常见的需求，但是针对边界情况的处理很多人却忽略掉了。针对比较长的屏幕，需要我们做特殊处理才能满足需求。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Web/API/Intersection_Observer_API\\" target=\\"_blank\\" rel=\\"noreferrer\\">Intersection Observer API</a></p>\\n"}]},"relativePath":"page/3/index.md","filePath":"page/[page].md"}`),e={name:"page/3/index.md"};function l(p,r,o,c,t,i){return n(),a("div")}const u=s(e,[["render",l]]);export{d as __pageData,u as default};
